    "kind": "lesson",
    "title": "Independent validation for advanced products",
    "order": 3,
    "readiness": "draft",
    "level": "L2",
    "estimatedMinutes": 35,
    "objectives": [
      {
        "id": "cgei-rs-o-49-validate",
        "statement": "Specify independent reference samples for time-series products and report validation by stratum, not only overall scores.",
        "action": "specify and report",
        "level": "L2",
        "competencyIds": [
          "cgei-comp-reproducibility",
          "cgei-comp-uncertainty"
        ]
      }
    ],
    "content": [
      {
        "id": "cgei-rs-49-3-ref",
        "kind": "prose",
        "title": "Independent reference data",
        "body": "Fused and time-series products need reference data not used in method tuning. Sources include field plots, VHR interpretation, and independent sensors. Reference uncertainty remains (Unit 4.7)—record it."
      },
      {
        "id": "cgei-rs-49-3-design",
        "kind": "prose",
        "title": "Sample design for time series",
        "body": "Design samples across seasons and strata (crop type, irrigation, cloud climate). Temporal support of the product must match the reference date. Avoid validating only the easiest clear-sky month."
      },
      {
        "id": "cgei-rs-49-3-stratum",
        "kind": "prose",
        "title": "Report by stratum",
        "body": "Overall metrics hide stratum failure (rare crops, urban fringe, cloudy mountains). Report accuracy or error rates by stratum, then overall. Link to Unit 4.7 rare-class lessons."
      },
      {
        "id": "cgei-rs-49-3-points",
        "kind": "key-points",
        "title": "Validation rules",
        "items": [
          "Independent of training/tuning",
          "Match temporal support",
          "Stratum-wise reporting",
          "Reference uncertainty stated"
        ]
      }
    ],
